/// <summary>
/// CB626_TMSEngineSOPackingSlip
/// Class responsible for the TSIG TOT calculation (no CCR)
/// </summary>
class METTMSShipmentItemGroupTOUOM_TOT extends METTMSShipmentItemGroupTOUOM
{
}

Method.Source:
/// <summary>
/// Method for the TSIG quantity UOM
/// </summary>
/// <returns>Shipment UOM TOT</returns>
METShipmentUOM shipmentUOM()
{
    return METConstants::unitTOT;
}

/// <summary>
/// Method to calculate TSIG volume (cube)
/// </summary>
/// <param name = "_quantity">TSIG quantity</param>
/// <returns>TSIG volume (cube)</returns>
METWHSPalletVolume cube(METQty _quantity)
{
    return sumRepackContainersByCommodityToteVolume;
}

/// <summary>
/// Method to calculate TSIG quantity
/// </summary>
/// <returns>TSIG quantity</returns>
METQty quantity()
{
    return sumRepackContainersByCommodityQty;
}

/// <summary>
/// Method to calculate TSIG weight
/// </summary>
/// <param name = "_quantity">TSIG quantity</param>
/// <returns>TSIG weight</returns>
METWHSPalletWeight weight(METQty _quantity)
{
    return lineTmpSum.LineWeight_BrokenCaseSecurity + lineTmpSum.LineWeight_BrokenCaseNonSecurity + sumRepackContainersByCommodityToteWeight;
}
